    assert client.post(
        "/login", json={"username": "bob", "password": "bob-pass", "otp": otp_bob}
    ).status_code == 200
    assert client.post(
        "/login", json={"username": "bob", "password": "x", "otp": otp_bob}
    ).status_code == 401


